"use client"

import * as React from "react"
import { Sign, type SignProps } from "@/components/ui/sign"
import type { SignShape } from "@/lib/0db/sign-shapes"

const shape: SignShape = {
  "word": "right",
  "line": [
    [
      [
        "M",
        21,
        5
      ],
      [
        "L",
        3,
        5
      ]
    ],
    [
      [
        "M",
        21,
        12
      ],
      [
        "L",
        9,
        12
      ]
    ],
    [
      [
        "M",
        21,
        19
      ],
      [
        "L",
        7,
        19
      ]
    ]
  ]
}

function SignAlignRightDots(props: Omit<SignProps, "shape" | "variant">) {
  return <Sign shape={shape} variant="dots" {...props} />
}

export { SignAlignRightDots, shape }
